def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    # Connect diagonally aligned 1s.
    one_lines = set()
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if abs(r2 - r1) == abs(c2 - c1):
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                one_lines.add(1 if dr == dc else -1)
                r, c = r1, c1
                while True:
                    if out[r][c] == bg:
                        out[r][c] = 1
                    if (r, c) == (r2, c2):
                        break
                    r += dr
                    c += dc

    # A 6 emits a full perpendicular diagonal when it lies on a 1-line,
    # or belongs to a diagonal containing multiple 6s parallel to that line.
    eligible = set()
    for r, c in sixes:
        for slope in one_lines:
            key = r - c if slope == 1 else r + c
            same_six_diag = [
                (rr, cc) for rr, cc in sixes
                if (rr - cc if slope == 1 else rr + cc) == key
            ]
            on_one_line = any(
                (r - c == rr - cc) if slope == 1 else (r + c == rr + cc)
                for rr, cc in ones
            )
            if len(same_six_diag) >= 2 or on_one_line:
                eligible.add((r, c))
                break

    for r0, c0 in eligible:
        # Perpendicular to slope +1 is slope -1, and vice versa.
        slope = -1 if 1 in one_lines else 1
        for r in range(h):
            c = c0 + slope * (r - r0)
            if 0 <= c < w and out[r][c] == bg:
                out[r][c] = 6

    return out
